package de.augmentia.qoc.infratest;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * Single persistent record of the {@code infratest} module.
 *
 * <p>The primary key is generated by the database. The entity is kept
 * package-private in behaviour: callers use {@link InfratestRepository}.</p>
 */
@Entity
@Table(name = "infratest_entry")
public class InfratestEntry {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "name", nullable = false, length = 255)
    private String name;

    @Column(name = "content", length = 1024)
    private String content;

    /** Required by JPA. */
    protected InfratestEntry() {
    }

    public InfratestEntry(String name, String content) {
        this.name = name;
        this.content = content;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getContent() {
        return content;
    }

    public void setContent(String content) {
        this.content = content;
    }
}
